 function schedule(){if(drawId!==null)return;if(typeof requestAnimationFrame==='function')drawId=requestAnimationFrame(()=>{drawId=null;draw();});else draw();}
 function draw(){if(!image)return;stage.style.maxWidth='min(100%, calc(var(--sr-image-height, 60vh) * '+((image.width||image.naturalWidth)/(image.height||image.naturalHeight))+'))';try{if(!paintStudioReference({canvas,processed,image,plan:getPlan(),original}))notify('unsupported');filename.textContent=imageName+' · '+canvas.width+' × '+canvas.height;}catch{notify('unsupported');}}
 function point(event){const rect=canvas.getBoundingClientRect();if(!rect.width||!rect.height)return null;return {x:Math.max(.02,Math.min(.98,(event.clientX-rect.left)/rect.width)),y:Math.max(.02,Math.min(.98,(event.clientY-rect.top)/rect.height))};}
