 stage.addEventListener('pointerdown',event=>{if(event.target!==canvas||!image||!anchorMode)return;updateMarker('subject',event);finish();anchorMode=false;stage.className='sr-stage';});stage.addEventListener('pointermove',event=>{if(drag)updateMarker(drag,event);});stage.addEventListener('pointerup',()=>{if(drag){drag=null;finish();}});stage.addEventListener('pointercancel',cancel);
