 async function loadImage(source){const request=++revision;loading=true;notify('loading');refresh();let next;try{next=await decode(source);studioReferenceCanvasSize(next.width||next.naturalWidth,next.height||next.naturalHeight);if(request!==revision){next.close?.();return false;}image?.close?.();image=next;next=null;imageName=String(source.name||'').split(/[\\/]/).pop();original=false;notify('ready');return true;}catch{next?.close?.();if(request===revision)notify('invalid');return false;}finally{if(request===revision){loading=false;refresh();}}}
 function clearImage(){revision++;loading=false;image?.close?.();image=null;imageName='';cancel();notify('');refresh();}
 function exportImage(){if(!image)return;try{const output=el('canvas'),fx=el('canvas'),p=getPlan();p.reference.split=0;if(!paintStudioReference({canvas:output,processed:fx,image,plan:p}))throw Error();output.toBlob(blob=>{if(!blob){notify('unsupported');return;}const url=URL.createObjectURL(blob),a=el('a');a.href=url;a.download='Prompt-Studio-light-sketch.png';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);},'image/png');}catch{notify('unsupported');}}
 function buildLights(p){const lang=getLanguage(),ids=p.lights.map(l=>l.id).join('|');if(language===lang&&lightList.dataset.lightIds===ids)return;language=lang;lightList.dataset.lightIds=ids;lightList.replaceChildren();lampNodes.clear();for(const [index,light]of p.lights.entries()){const card=el('div','','sr-light'),name=el('strong');card.append(name);const set=(key,value)=>{const n=getPlan(),l=n.lights.find(l=>l.id===light.id);if(l)l[key]=value;return n;};const strength=range(card,'intensity',0,100,1,v=>set('intensity',v)),size=range(card,'softness',.1,3,.1,v=>set('size',v)),kelvin=range(card,'temperature',2000,10000,100,v=>set('kelvin',v)),gel=checkbox(card,'gel',v=>commit(set('colorMode',v?'gel':'temperature'))),color=el('input');color.type='color';color.setAttribute('aria-label',t().gel);color.dataset.srLight=light.id;color.addEventListener('input',()=>preview(set('color',color.value)));color.addEventListener('change',finish);card.append(color);lightList.append(card);lampNodes.set(light.id,{name,index,strength,size,kelvin,gel,color});}}
 function refresh(){const p=normalizeStudioPlan(getPlan());canvas.setAttribute('aria-label',t().title);if(largeDialog)largeDialog.setAttribute('aria-label',t().title);for(const [n,key]of textNodes)n.textContent=t()[key];status.textContent=t()[statusKey]||'';canvas.hidden=!image;empty.hidden=Boolean(image);markers.hidden=!image||!p.reference.showMarkers;clear.disabled=!image&&!loading;exportButton.disabled=!image||loading;filename.textContent=imageName?imageName+' · '+canvas.width+' × '+canvas.height:'';originalBox.checked=original;markersBox.checked=p.reference.showMarkers;buildLights(p);for(const l of p.lights){const nodes=lampNodes.get(l.id);nodes.name.textContent=(nodes.index+1)+'. '+(l.name||l.role);nodes.strength.value=String(l.intensity);nodes.size.value=String(l.size);nodes.kelvin.value=String(l.kelvin);nodes.kelvin.parentElement.hidden=l.colorMode==='gel';nodes.gel.checked=l.colorMode==='gel';nodes.color.hidden=l.colorMode!=='gel';nodes.color.value=l.color;for(const input of [nodes.strength,nodes.size,nodes.kelvin])input.parentElement.querySelector('output').textContent=input.value;}
  const c=studioReferenceCamera(p);cameraReadout.textContent=`${t().yaw} ${c.yaw}° · ${t().pitch} ${c.pitch}° · ${c.height} m · ${c.lens} mm`;for(const [key,ref]of controls){if(['intensity','softness','temperature'].includes(key))continue;const value=key in c?c[key]:p.reference[key];if(ref.input.value!==String(value))ref.input.value=String(value);ref.value.textContent=String(value);ref.input.setAttribute('aria-label',t()[key]);}markers.replaceChildren();if(image){marker('subject',p.reference.anchor,'●','#ec655d');for(const [index,l]of p.lights.entries())marker(l.id,studioReferencePoint(p,l),String(index+1),studioLightColor(l));}schedule();
 }
 globalThis.addEventListener?.('beforeunload',event=>{if(pending){event.preventDefault();event.returnValue='';}});refresh();return {refresh,loadImage,openLarge,clear:clearImage,getReference:()=>({filename:imageName,loaded:Boolean(image)}),cancel};
